use velnor_actions_workflow_renderer::agents_md::render_agents_md;

#[test]
fn the_velnor_gen_exemption_is_limited_to_direct_regular_files()
-> Result<(), Box<dyn std::error::Error>> {
    let file = render_agents_md("0.0.0")?;
    assert!(
        file.bytes.contains(
            "regular files directly in `.github/workflows/` whose first line is the `# Generated by velnor-gen.` header"
        ),
        "{}",
        file.bytes
    );
    Ok(())
}
